import{_ as s,C as i,o as n,c as r,a5 as t,E as o}from"./chunks/framework.C1a7WKBV.js";const b=JSON.parse('{"title":"新手从这里开始","description":"一条从第一次使用 AI 到独立完成真实项目的学习路线，包含诊断、练习、验收和进度记录。","frontmatter":{"title":"新手从这里开始","description":"一条从第一次使用 AI 到独立完成真实项目的学习路线，包含诊断、练习、验收和进度记录。"},"headers":[],"relativePath":"start/index.md","filePath":"start/index.md","lastUpdated":1788838685000}'),l={name:"start/index.md"};function d(p,a,h,c,u,_){const e=i("LearningChecklist");return n(),r("div",null,[a[0]||(a[0]=t('<h1 id="新手从这里开始" tabindex="-1">新手从这里开始 <a class="header-anchor" href="#新手从这里开始" aria-label="Permalink to &quot;新手从这里开始&quot;">​</a></h1><p>这不是一份“把所有文章都看完”的目录。你的目标是完成四次能力升级：<strong>会提问 → 会选择 → 会交付 → 会复盘</strong>。每一关都必须留下可检查的作品；看懂但做不出来，还没有过关。</p><div class="tip custom-block"><p class="custom-block-title">第一次来，只做这三件事</p><ol><li>用下面的自测确定起点；2. 选择一个主力工具；3. 今天完成一个 20 分钟小任务。不要先安装五个软件。</li></ol></div><h2 id="_1-先判断你从哪一关开始" tabindex="-1">1. 先判断你从哪一关开始 <a class="header-anchor" href="#_1-先判断你从哪一关开始" aria-label="Permalink to &quot;1. 先判断你从哪一关开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现状</th><th>起点</th><th>今天的动作</th></tr></thead><tbody><tr><td>不清楚模型、API、客户端的区别</td><td>基础关</td><td>阅读《<a href="/ai-handbook/concepts/model-api-client">模型、服务、API 与客户端</a>》</td></tr><tr><td>会聊天，但结果经常不符合预期</td><td>表达关</td><td>用《<a href="/ai-handbook/concepts/prompt-basics">提示词入门</a>》重写一个真实需求</td></tr><tr><td>不知道 Claude Code、Codex、Cursor 怎么选</td><td>选型关</td><td>完成《<a href="/ai-handbook/tools/selector">60 秒工具选择器</a>》</td></tr><tr><td>已装好工具，但不敢让它改项目</td><td>实战关</td><td>跟做《<a href="/ai-handbook/tutorials/first-project">第一个 AI 编程项目</a>》</td></tr><tr><td>能生成代码，但经常改坏或返工</td><td>工程关</td><td>学《<a href="/ai-handbook/tips/ai-coding-principles">通用 AI 编程方法论</a>》</td></tr><tr><td>已能独立交付，想建立稳定体系</td><td>专家关</td><td>按《<a href="/ai-handbook/tips/roadmap">成长路径</a>》做项目复盘与规则沉淀</td></tr></tbody></table><h2 id="_2-四周最短学习路线" tabindex="-1">2. 四周最短学习路线 <a class="header-anchor" href="#_2-四周最短学习路线" aria-label="Permalink to &quot;2. 四周最短学习路线&quot;">​</a></h2><h3 id="_2-1-第-1-周-会表达-也会怀疑" tabindex="-1">2.1 第 1 周：会表达，也会怀疑 <a class="header-anchor" href="#_2-1-第-1-周-会表达-也会怀疑" aria-label="Permalink to &quot;2.1 第 1 周：会表达，也会怀疑&quot;">​</a></h3><p><strong>学习内容</strong>：LLM、Token、上下文、结构化提示词、事实核验。</p><p><strong>每天练习</strong>：把一个模糊任务改写为“目标 + 背景 + 约束 + 验收标准”，要求 AI 先复述需求，再给结果。</p><p><strong>过关作品</strong>：同一个任务保留原提示词、改进版提示词、两次输出和你的对比结论。</p><h3 id="_2-2-第-2-周-选定工具并跑通环境" tabindex="-1">2.2 第 2 周：选定工具并跑通环境 <a class="header-anchor" href="#_2-2-第-2-周-选定工具并跑通环境" aria-label="Permalink to &quot;2.2 第 2 周：选定工具并跑通环境&quot;">​</a></h3><ol><li>用《<a href="/ai-handbook/tools/selector">工具选择器</a>》选一个主力工具。</li><li>图形界面新手优先 <a href="/ai-handbook/clients/vscode-copilot">VS Code + GitHub Copilot</a> 或 <a href="/ai-handbook/clients/cursor">Cursor</a>。</li><li>愿意用终端可选 <a href="/ai-handbook/clients/claude-code">Claude Code</a>、<a href="/ai-handbook/clients/codex-cli">Codex CLI</a> 或 <a href="/ai-handbook/clients/gemini-cli">Gemini CLI</a>。</li><li>数据必须留在本机，阅读 <a href="/ai-handbook/clients/local-ai">Ollama 与 LM Studio</a>。</li></ol><p><strong>过关作品</strong>：让工具读取一个练习目录、创建文件、执行检查，并由你确认改动内容。</p><h3 id="_2-3-第-3-周-完成一个小而完整的项目" tabindex="-1">2.3 第 3 周：完成一个小而完整的项目 <a class="header-anchor" href="#_2-3-第-3-周-完成一个小而完整的项目" aria-label="Permalink to &quot;2.3 第 3 周：完成一个小而完整的项目&quot;">​</a></h3><p>跟做《<a href="/ai-handbook/tutorials/first-project">第一个 AI 编程项目</a>》。重点不是项目多复杂，而是走完整个闭环：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求 → 验收标准 → 方案 → 小步实现 → 自动检查 → 人工体验 → 复盘</span></span></code></pre></div><p><strong>过关作品</strong>：一个能运行的项目、一份 README、一条验证命令、一份已知问题清单。</p><h3 id="_2-4-第-4-周-独立排错与复盘" tabindex="-1">2.4 第 4 周：独立排错与复盘 <a class="header-anchor" href="#_2-4-第-4-周-独立排错与复盘" aria-label="Permalink to &quot;2.4 第 4 周：独立排错与复盘&quot;">​</a></h3><p>遇到问题时，不要把一整屏报错直接丢给 AI。先用《<a href="/ai-handbook/help/troubleshooting">通用排错手册</a>》定位属于环境、认证、网络、配置、模型还是项目代码层。</p><p><strong>过关作品</strong>：记录一次真实故障的现象、最小复现、根因、修复和防复发规则。</p><h2 id="_3-学习进度表" tabindex="-1">3. 学习进度表 <a class="header-anchor" href="#_3-学习进度表" aria-label="Permalink to &quot;3. 学习进度表&quot;">​</a></h2>',21)),o(e),a[1]||(a[1]=t(`<h2 id="_4-每次向-ai-下任务的固定模板" tabindex="-1">4. 每次向 AI 下任务的固定模板 <a class="header-anchor" href="#_4-每次向-ai-下任务的固定模板" aria-label="Permalink to &quot;4. 每次向 AI 下任务的固定模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：要完成什么，以及谁会使用它。</span></span>
<span class="line"><span>现状：已有文件、技术栈、已尝试的方法。</span></span>
<span class="line"><span>范围：这次要改什么，不要改什么。</span></span>
<span class="line"><span>约束：平台、版本、风格、性能、安全要求。</span></span>
<span class="line"><span>验收：必须通过哪些命令和人工检查。</span></span>
<span class="line"><span>过程：先检查现状并给计划；小步修改；每步验证；最后汇总差异和风险。</span></span></code></pre></div><p>不会填的字段可以写“不确定，请先检查并给出选项”，比完全省略更有效。</p><h2 id="_5-想开发-ai-产品-走这条进阶支线" tabindex="-1">5. 想开发 AI 产品，走这条进阶支线 <a class="header-anchor" href="#_5-想开发-ai-产品-走这条进阶支线" aria-label="Permalink to &quot;5. 想开发 AI 产品，走这条进阶支线&quot;">​</a></h2><p>完成第一个项目后，如果目标是构建 AI 应用而不只是使用编程助手，按以下顺序继续：</p><ol><li>从《<a href="/ai-handbook/development/">AI 应用开发</a>》建立生产系统全景；</li><li>用《<a href="/ai-handbook/development/production-architecture">生产级 AI 应用架构</a>》划分模型与确定性程序的职责；</li><li>在知识问答场景学习《<a href="/ai-handbook/development/rag-engineering">RAG 检索增强工程</a>》；</li><li>用《<a href="/ai-handbook/development/evaluation-driven-development">AI 评测驱动开发</a>》建立发布门禁；</li><li>任务需要多步动态行动时，再进入《<a href="/ai-handbook/agents/">Agent 工程</a>》专题。</li></ol><p>过关作品不是一张架构图，而是一份包含任务定义、失败边界、评测样本、预算和回滚路径的最小技术方案。</p><h2 id="_6-从会用到专家的分界线" tabindex="-1">6. 从会用到专家的分界线 <a class="header-anchor" href="#_6-从会用到专家的分界线" aria-label="Permalink to &quot;6. 从会用到专家的分界线&quot;">​</a></h2><p>专家不是记住更多产品名，而是稳定做到下面五件事：</p><ol><li><strong>把模糊目标变成可验收任务</strong>，知道什么时候应该先澄清。</li><li><strong>为信息选择正确来源</strong>，重要事实回到官方文档或原始数据核验。</li><li><strong>控制改动半径</strong>，使用版本控制、小步提交和回滚点。</li><li><strong>建立验证闭环</strong>，不把“AI 说完成了”当成完成。</li><li><strong>沉淀可复用规则</strong>，把踩坑记录写进项目文档、检查脚本和模板。</li></ol><p>下一步不要继续浏览：现在就选中进度表里的第一项开始做。</p>`,11))])}const f=s(l,[["render",d]]);export{b as __pageData,f as default};
